import { chromium } from '/home/davi-benucci/Área de trabalho/WFlyer/node_modules/playwright/index.mjs';
import { writeFile } from 'node:fs/promises';
const browser=await chromium.launch({headless:true});const records=[];
try {
for(const viewport of [{width:1440,height:900},{width:1536,height:900},{width:1920,height:917}]) {
 const page=await browser.newPage({viewport});const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3100/__visual-lab/story/motion',{waitUntil:'domcontentloaded'});
 await page.waitForSelector('[data-score-projection="horizontal-enhanced"]',{timeout:60000});
 await page.evaluate(async()=>{await document.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))});
 const nav=page.getByRole('link',{name:'Projetos',exact:true});if(await nav.count())await nav.first().click();
 await page.keyboard.press('Tab');
 const result=await page.evaluate(async()=>{
 const track=document.querySelector('[data-motion-track]');const layer=document.querySelector('[data-story-score-layer]');const cards=[...document.querySelectorAll('[data-project-card-item]')];
 const plain=r=>({x:r.x,y:r.y,width:r.width,height:r.height});
 const read=(el)=>{const a=el.querySelector('a'),tr=track.getBoundingClientRect(),cr=el.getBoundingClientRect(),lr=a.getBoundingClientRect(),s=getComputedStyle(el),ls=getComputedStyle(a);return {card:{x:cr.x-tr.x,y:cr.y-tr.y,width:cr.width,height:cr.height},link:{x:lr.x-tr.x,y:lr.y-tr.y,width:lr.width,height:lr.height},outlineWidth:parseFloat(ls.outlineWidth),outlineOffset:parseFloat(ls.outlineOffset),outlineStyle:ls.outlineStyle,focusVisible:a.matches(':focus-visible'),transform:s.transform,transitionDuration:s.transitionDuration,animations:el.getAnimations().map(a=>({time:a.currentTime,state:a.playState})),track:plain(tr)}};
 const staff=[...document.querySelectorAll('[data-score-branch="professional"] [data-score-role="staff-line"]')].map(el=>{const m=el.getScreenCTM(),tr=track.getBoundingClientRect();return {id:el.getAttribute('data-score-primitive-id'),tag:el.tagName,points:el.getAttribute('points'),d:el.getAttribute('d'),stroke:el.getAttribute('stroke-width'),matrix:[m.a,m.b,m.c,m.d,m.e-tr.x,m.f-tr.y]}});
 document.activeElement?.blur();await new Promise(r=>setTimeout(r,450));
 const idle=cards.map(read),states=[];
 for(const el of cards){
 el.querySelector('a').focus({preventScroll:true});
 const immediate=read(el);await new Promise(r=>requestAnimationFrame(r));const firstFrame=read(el);await new Promise(r=>requestAnimationFrame(r));const secondFrame=read(el);await new Promise(r=>setTimeout(r,450));const settled=read(el);states.push({projectIndex:Number(el.dataset.projectPosition),immediate,firstFrame,secondFrame,settled});el.querySelector('a').blur();await new Promise(r=>setTimeout(r,450));
 }
 return {idle,states,staff,anchors:JSON.parse(layer.getAttribute('data-score-project-visit-anchors')),mode:layer.getAttribute('data-score-projection')};
 });records.push({viewport,result,errors});console.log(JSON.stringify({viewport,states:result.states.map(s=>({index:s.projectIndex,immediate:s.immediate,first:s.firstFrame}))}));await page.close();
}
await writeFile('/tmp/wflyer-projects-ink-high/focus-envelopes.json',JSON.stringify({schema:'focused-projects-interaction-probe/v1',records},null,2));
}finally{await browser.close()}
